__NUXT_JSONP__("/think-tanks/columnas/lo_que_si_podemos_hacer_tanques_de_pensamiento_para_un_mejor_gobierno", (function(a,b,c,d,e,f,g,h,i,j,k,l,m,n,o,p,q,r,s,t,u,v,w,x,y,z,A,B,C,D,E,F){return {data:[{post:{slug:"lo_que_si_podemos_hacer_tanques_de_pensamiento_para_un_mejor_gobierno",title:"LO QUE SÍ PODEMOS HACER: TANQUES DE PENSAMIENTO PARA UN MEJOR GOBIERNO",date:"2016-07-07T23:06:32.926Z",img:"https:\u002F\u002Fucarecdn.com\u002Fc94192fc-17f6-4974-a3ad-af265cae83cb\u002F","img-alt":"cabeza con engranes pensando en un mejor gobierno",autor:"José Luis Chicoma",medio:r,link:"https:\u002F\u002Festepais.com\u002Farticulo.php?id=593&t=lo-que-si-podemos-hacer-tanques-de-pensamiento-para-un-mejor-gobierno",category:n,extracto:s,toc:[],body:{type:m,children:[{type:b,tag:c,props:{},children:[{type:b,tag:e,props:{},children:[{type:a,value:"El cambio que puede generar el equipo multidisciplinario de un think tank en política pública puede ser realmente significativo para un mejor Gobierno."}]}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:s}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Sin embargo, presionar para tener un Gobierno más responsable sí es posible. México tiene una sociedad civil fuerte, innovadora, activista y cada vez mejor organizada para lograrlo. Además, cuenta con algunos funcionarios públicos muy calificados que podrían impulsar el cambio. El reto es dantesco. México figura entre los países con más desvío del gasto público del mundo y más corrupción.1"}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Para cambiar se requiere la voluntad de políticos y funcionarios públicos, así como presión de la sociedad civil. Es aquí donde tratamos de hacer la diferencia los "},{type:b,tag:e,props:{},children:[{type:a,value:k}]},{type:a,value:" o centros de pensamiento político. ¿Qué hacemos? Diagnosticar, investigar y proponer políticas públicas que mejoren el Gobierno."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"A veces nadie nos entiende. Cuando decimos que trabajamos en un "},{type:b,tag:e,props:{},children:[{type:a,value:o}]},{type:a,value:", siempre nos preguntan: ¿"},{type:b,tag:e,props:{},children:[{type:a,value:t}]},{type:a,value:" qué?, ¿en qué piensan?, ¿hacen consultorías? Este tipo de organizaciones nace a mediados del siglo pasado, en una versión 1.0, como “universidades sin estudiantes”. Posteriormente, evolucionan para poner más énfasis en la coyuntura, dotar de recursos humanos al Gobierno, impulsar mejor sus propuestas e influir en la opinión pública."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"En "},{type:b,tag:f,props:{href:"https:\u002F\u002Fwww.ethos.org.mx\u002F",rel:[g,h,i],target:j},children:[{type:a,value:"Ethos Laboratorio de Políticas Públicas"}]},{type:a,value:" nos concentramos en promover propuestas que hagan que el Gobierno sea más responsable, transparente y eficiente. Apuntamos a ser un "},{type:b,tag:e,props:{},children:[{type:a,value:o}]},{type:a,value:" 5.0: usamos herramientas tecnológicas, contamos con un equipo multidisciplinario e innovador, realizamos alianzas con otras organizaciones de la sociedad civil y, en general, tenemos un rol propositivo."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Lograr que el Gobierno mexicano sea más transparente y eficiente no es tarea fácil. Hace cuatro años llegué a México, después de una larga carrera en el sector público peruano. Tenía en mente lo que otro peruano dijo de México en 1990. Mario Vargas Llosa describió el sistema mexicano como una “dictadura perfecta”, justamente por los fuertes incentivos perversos que se desarrollaron durante décadas de no alternancia política, que debilitaban la crítica frontal y real al Gobierno."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Todavía quedan muchos lastres de ese sistema. En ciertas ocasiones, cuando hemos criticado abiertamente la labor del Gobierno, nos han cerrado las puertas para un diálogo sobre nuestras propuestas. Sin embargo, en muchos otros casos, hemos logrado persuadir a los funcionarios públicos sobre la importancia de un Gobierno más transparente y basado en resultados."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Desde hace años investigamos el uso de las asociaciones público-privadas (APP) para promover la innovación, publicando propuestas y guías prácticas para su implementación. Este instrumento, que normalmente se emplea para la construcción y mantenimiento de carreteras o aeropuertos, todavía no se usa en México para promover proyectos grandes de innovación tecnológica. El apoyo actual a la innovación se realiza con subsidios pequeños que no tienen un impacto significativo ni son evaluados en función de sus resultados."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Nuestra propuesta es que el país aumentará su crecimiento económico si apuesta en grande por la innovación, y pasará del “hecho en México” al “creado en México”. Las APP son un buen instrumento porque promueven la inversión transparente con resultados. Sin embargo, dado que comprometen recursos públicos por muchos años, su aprobación requiere estudios numerosos y complejos. Además, como son algo nuevo, no son vistas con buenos ojos por algunos funcionarios públicos adversos al riesgo."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Por eso, cuando lo sugerimos por primera vez, nadie creía que lograríamos su implementación en México. Sin embargo, hace dos meses, el Gobierno de Jalisco anunció que convocaría la primera APP en innovación en el sector de salud, a fin de fortalecer un eslabón estratégico dentro de la industria farmacéutica. Desde que comenzamos a apoyarlos en esta tarea, hemos encontrado un grupo de funcionarios públicos muy comprometidos con los resultados, la colaboración con "},{type:b,tag:e,props:{},children:[{type:a,value:k}]},{type:a,value:" y, principalmente, la búsqueda de herramientas innovadoras que les permitan aumentar el bienestar público de forma más eficiente."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"La investigación de políticas públicas no tiene que ser meramente académica y teórica. Puede tener resultados concretos. En México hay muchos sectores de los gobiernos locales y federal que requieren mayor fiscalización y propuestas para ser más transparentes y trabajar en función de resultados."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"El cambio que puede generar el equipo de un "},{type:b,tag:e,props:{},children:[{type:a,value:o}]},{type:a,value:" —compuesto por economistas, abogados, politólogos, comunicadores y otros especialistas— a través de propuestas de política pública es significativo para un mejor Gobierno. Personalmente, cuando estoy en organizaciones rígidas con muchas reglas, no me siento cómodo ni productivo. Por eso me inspira ser parte de un espacio multidisciplinario que fomente el libre pensamiento para proponer políticas innovadoras. Si le gusta la investigación con impacto, quiere servir a la sociedad desde fuera del Gobierno y es creativo, tal vez su lugar esté en un "},{type:b,tag:e,props:{},children:[{type:a,value:o}]},{type:a,value:". "}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:u},{type:b,tag:f,props:{href:"http:\u002F\u002Fwww.estepais.com\u002Farticulo.php?id=593&t=lo-que-si-podemos-hacer-tanques-de-pensamiento-para-un-mejor-gobierno",rel:[g,h,i],target:j},children:[{type:a,value:r}]}]}]},dir:p,path:"\u002Fcolumnas\u002Flo_que_si_podemos_hacer_tanques_de_pensamiento_para_un_mejor_gobierno",extension:q,createdAt:"2023-06-19T05:11:58.471Z",updatedAt:"2022-09-15T15:48:00.230Z"},columnas:[{slug:"collaboration_under_the_mantle_of_populism",title:"Collaboration under the mantle of populism",date:"2025-07-10T17:20:20.737Z",img:"https:\u002F\u002Fucarecdn.com\u002F2c75323d-b65f-4d5a-8e29-fa2c0b7f4977\u002F","img-alt":"colaboración",autor:"Liliana Alvarado ",medio:"On Think Tanks",link:"https:\u002F\u002Fonthinktanks.org\u002Farticles\u002Fcollaboration-under-the-mantle-of-populism\u002F",category:n,extracto:v,toc:[],body:{type:m,children:[{type:b,tag:c,props:{},children:[{type:a,value:"In general terms, collaboration involves establishing a relationship with other actors —whether similar or different— with the aim of achieving a specific goal. In order for collaboration to be effective, there are several elements that must be in place: (1) a shared objective, (2) transparent and fluid communication, (3) an environment of mutual trust, and (4) a favorable context. Collaboration tends to be more successful when the benefits are clear or when it addresses a pressing need of the parties involved."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"In practice, the contextual factor has proven to carry significant weight. In the specific case of the Latin American region, some populist governments—whether left- or right-leaning—have sought to divide their populations in various ways (rich vs. poor, right vs. left, liberals vs. conservatives). Generally speaking, these labels have been used by such regimes to separate the “good” from the “bad”."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"According to this perspective, the “bad guys” are all those individuals or groups who think differently from the government or ruling party. As a result, criticism of government actions—or demands for openness, transparency, and accountability—can often be met with hostility. This undoubtedly hinders the work of counterweights, which include autonomous or independent entities, the business sector, journalists, and research centres known as think tanks."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"In the case of the organisations mentioned above, they face a twofold challenge that negatively affects their work. The first is the difficulty in maintaining open communication channels, establishing relationships, or collaborating with the current government. This engagement—so crucial for achieving policy impact—becomes nearly impossible. The second issue lies in the difficulty of fostering collaboration among non-governmental actors themselves, such as civil society organisations, the private sector, universities, and the media. All of these stakeholders play a key role in advancing advocacy strategies that seek to drive policy change."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:v}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"At times, the political and economic influence of third countries also affects collaboration. In this regard, funding from international development agencies to think tanks has been shifting significantly over the last few years. In several countries, these funds have been reduced and are now granted for shorter periods, forcing organisations to continually search for resources. This situation was further exacerbated by the “Trump factor,” as the U.S. president had earlier decided to eliminate foreign aid provided by the United States Agency for International Development (USAID) to other countries."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Currently, securing three or four separate funding sources may be necessary to cover what was once achieved with just one. This resource scarcity has made it increasingly difficult to form consortia to access funding. While some donors encourage collaboration among two or more think tanks to design and implement projects, the overall reduction in available resources has made it less feasible to split funding among multiple parties."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"It seems that both national and international contexts are undermining collaborative efforts. In the case of think tanks, this has led to new challenges in how they operate, particularly in certain regions of the world. Yet, working in isolation does not appear to be a viable alternative either. Will it become increasingly common for think tanks to form alliances with actors from opposing ideological backgrounds? Is it possible for civil society organizations to collaborate with governments they do not trust —or that seek to delegitimize their work? Where should we draw the line between a healthy diversity of perspectives and the values that a collaboration can tolerate without compromising its purpose?"}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Think tanks are at a crossroads where they must determine whether a less genuine and sincere form of collaboration is still desirable, or at least strategically necessary. This dilemma applies not only to relationships with incumbent governments but also to those with non-governmental actors. Do the ends justify the means? There is no definitive answer. In some cases, populism and its effects have been gradually expanding, prompting think tanks to adapt to shifting dynamics and to test various strategies in an effort to understand what works and what does not."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"It is challenging to predict the future of collaboration under the influence of populism, which is increasingly drawing more people into its sphere. In this context, think tanks must find ways to remain relevant and loyal to their principles, without legitimising positions that are eroding democratic institutions. The challenge lies in not losing sight of what gives meaning to their existence: contributing to the public interest through research and independent thinking."}]}]},dir:p,path:"\u002Fcolumnas\u002Fcollaboration_under_the_mantle_of_populism",extension:q,createdAt:w,updatedAt:w},{slug:"cuatro_formas_creativas_en_las_que_colaboran_los_think_tanks_con_periodistas",title:"CUATRO FORMAS CREATIVAS EN LAS QUE COLABORAN LOS THINK TANKS CON PERIODISTAS ",date:"2018-11-13T00:03:36.335Z",img:"https:\u002F\u002Fucarecdn.com\u002F0cca2aa0-fe73-4d2d-ab07-2ae60d598681\u002F",autor:"Ethos",medio:x,link:"https:\u002F\u002Fwww.arenapublica.com\u002Fblog-ethos-laboratorio\u002Fthink-tanks-y-periodistas-4-formas-de-colaboracion",category:n,extracto:"Los *think tanks* a nivel global tenemos problemas para comunicar lo que hacemos. Muchas veces cuando les contamos a nuestros amigos y familiares sobre nuestro trabajo, las reacciones más frecuentes son: “¿*think* qué?”, “¿en qué piensan?”, “¿tanque? debe estar relacionado con las fuerzas armadas”.",toc:[],body:{type:m,children:[{type:b,tag:c,props:{},children:[{type:b,tag:e,props:{},children:[{type:a,value:"Los think tanks se enfrentan al reto de difundir los conocimientos que producen. A través de diversas estrategias innovadoras pueden generar una comunicación efectiva con la sociedad."}]}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Los "},{type:b,tag:e,props:{},children:[{type:a,value:k}]},{type:a,value:" a nivel global tenemos problemas para comunicar lo que hacemos. Muchas veces cuando les contamos a nuestros amigos y familiares sobre nuestro trabajo, las reacciones más frecuentes son: “¿"},{type:b,tag:e,props:{},children:[{type:a,value:t}]},{type:a,value:" qué?”, “¿en qué piensan?”, “¿tanque? debe estar relacionado con las fuerzas armadas”."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"A nivel mundial, muchos centros de pensamiento y estudios, organismos de desarrollo y otros, "},{type:b,tag:l,props:{},children:[{type:a,value:"no logramos comunicar el conocimiento que generamos"}]},{type:a,value:". Entre una serie de Netflix, o los feeds de las redes sociales, y un estudio de políticas públicas, ¿qué escogería consumir usted? El Banco Mundial hizo un "},{type:b,tag:f,props:{href:"http:\u002F\u002Fdocuments.worldbank.org\u002Fcurated\u002Fen\u002F387501468322733597\u002Fpdf\u002FWPS6851.pdf",rel:[g,h,i],target:j},children:[{type:a,value:"estudio"}]},{type:a,value:" hace unos años en el que encontró que el 31% de sus documentos nunca habían sido descargados. Y se trata de textos dirigidos a expertos que deberían preferir la lectura de dichos documentos, frente a ver La Casa de las Flores."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Si el Banco Mundial es una de las instituciones con más recursos y especialistas para generar y difundir conocimiento sobre desarrollo económico y político, ¿qué podemos hacer instituciones mucho más pequeñas y sin tantos recursos para llegar a tener más influencia? Felizmente, en México hay muchos casos de innovación que responden cómo hacerlo, provenientes de "},{type:b,tag:e,props:{},children:[{type:a,value:k}]},{type:a,value:" y organizaciones similares. Se trata de "},{type:b,tag:l,props:{},children:[{type:a,value:"alianzas con medios creativos, trabajo colaborativo con periodistas de investigación, uso de herramientas tecnológicas"}]},{type:a,value:", entre otros. Acá les damos 4 ejemplos sobre cómo lograrlo:"}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:b,tag:l,props:{},children:[{type:a,value:y}]}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"“"},{type:b,tag:l,props:{},children:[{type:a,value:"PAOLA"}]},{type:a,value:". Era trabajadora sexual. Fue asesinada hace dos años en el coche de un cliente. "},{type:b,tag:l,props:{},children:[{type:a,value:"El principal sospechoso, un exmilitar, sigue prófugo"}]},{type:a,value:".”"}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Para difundir su reporte "},{type:b,tag:f,props:{href:"https:\u002F\u002Fwww.mexicoevalua.org\u002Fwp-content\u002Fuploads\u002F2018\u002F09\u002F5013HomicidiosCDMX.pdf",rel:[g,h,i],target:j},children:[{type:a,value:y}]},{type:a,value:", "},{type:b,tag:f,props:{href:"https:\u002F\u002Fwww.mexicoevalua.org\u002F",rel:[g,h,i],target:j},children:[{type:a,value:"México Evalúa"}]},{type:a,value:" creó una alianza con El País, de lo cual resultó el reportaje "},{type:b,tag:f,props:{href:"https:\u002F\u002Felpais.com\u002Fespeciales\u002F2018\u002Fviolencia-cdmx\u002F",rel:[g,h,i],target:j},children:[{type:a,value:"Matar o morir"}]},{type:a,value:". La plataforma enlaza testimonios, numeralias, videos, frases y gráficas interactivas, lo que da un sentido más humano al informe."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Asimismo, Fusión generó "},{type:b,tag:f,props:{href:"https:\u002F\u002Fwww.facebook.com\u002FFusionMexicoOficial\u002Fvideos\u002F732797000392788\u002FUzpfSTEwMDAwMjYzMjY5MjYwODoxNzY0MjUyNjAwMzM5MTQ2\u002F",rel:[g,h,i],target:j},children:[{type:a,value:"minidocumentales"}]},{type:a,value:" y México.com publicó una serie de "},{type:b,tag:f,props:{href:"https:\u002F\u002Fwww.mexico.com\u002Fespecial\u002Fhomicidios-en-cdmx\u002F",rel:[g,h,i],target:j},children:[{type:a,value:"reportajes"}]},{type:a,value:" relacionados con el contenido del informe."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:b,tag:l,props:{},children:[{type:a,value:"La Estafa Maestra"}]}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Sabemos que hay muchísima corrupción. Pero como es un fenómeno que se hace a escondidas y se trata de ocultar por todos los medios posibles, no es fácil encontrar sus mecanismos ni descubrirla a la opinión pública. Sin embargo, "},{type:b,tag:f,props:{href:"https:\u002F\u002Fwww.animalpolitico.com\u002F",rel:[g,h,i],target:j},children:[{type:a,value:"Animal Político"}]},{type:a,value:z},{type:b,tag:f,props:{href:A,rel:[g,h,i],target:j},children:[{type:a,value:B}]},{type:a,value:"(MCCI) hicieron exactamente eso: "},{type:b,tag:f,props:{href:"https:\u002F\u002Fwww.animalpolitico.com\u002Festafa-maestra\u002F",rel:[g,h,i],target:j},children:[{type:a,value:"revelaron que dependencias del Gobierno Federal"}]},{type:a,value:" y universidades públicas "},{type:b,tag:l,props:{},children:[{type:a,value:"desviaron 7,670 millones de pesos"}]},{type:a,value:" en contratos ilegales a 186 empresas, de la cuales 128 eran empresas fantasma."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"El equipo de periodistas presentó la información con un formato interactivo y transmedia. Empleó videos, testimoniales, un cómic, infografías, numeralias y hasta emojis. Además vincularon a los becarios del programa Prensa y Democracia ("},{type:b,tag:f,props:{href:"https:\u002F\u002Ftwitter.com\u002Fprogramaprende?lang=es",rel:[g,h,i],target:j},children:[{type:a,value:"PRENDE"}]},{type:a,value:") de la "},{type:b,tag:f,props:{href:"http:\u002F\u002Fibero.mx\u002F",rel:[g,h,i],target:j},children:[{type:a,value:"Universidad Iberoamericana"}]},{type:a,value:" para colaborar en la investigación. Gracias a este trabajo, la Auditoría Superior de la Federación reconoció esta red de corrupción y el Servicio de Administración Tributaria inició una investigación contra empresas fantasma."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:b,tag:l,props:{},children:[{type:a,value:"Por qué se cayó mi edificio"}]}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"“Los habitantes en la Ciudad de México saben qué hacer durante un sismo; cómo salir de un departamento o dónde resguardarse mejor. Quienes han fallado han sido las autoridades.”"}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"A través de un trabajo colaborativo entre la ciudadanía, investigadores y periodistas, "},{type:b,tag:f,props:{href:A,rel:[g,h,i],target:j},children:[{type:a,value:B}]},{type:a,value:"presentó un "},{type:b,tag:f,props:{href:"https:\u002F\u002Fmiedificio.contralacorrupcion.mx\u002F",rel:[g,h,i],target:j},children:[{type:a,value:"micrositio"}]},{type:a,value:" que incluye un "},{type:b,tag:l,props:{},children:[{type:a,value:"recorrido por 28 construcciones"}]},{type:a,value:" en las que se detectaron actos de corrupción. A través de ilustraciones, fotografías y el uso del periodismo narrativo se entiende lo vivido en cada una de ellas.  Y se demuestra que el fallecimiento de muchas personas y daños provocados por el sismo del 19 de septiembre de 2017 pudieron haberse evitado si se respetaran las reglas para realizar construcciones."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:b,tag:l,props:{},children:[{type:a,value:C}]}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"La designación de los funcionarios públicos en México sigue siendo una área gris sobre la que "},{type:b,tag:f,props:{href:"http:\u002F\u002Ffundar.org.mx\u002F",rel:[g,h,i],target:j},children:[{type:a,value:"Fundar"}]},{type:a,value:z},{type:b,tag:f,props:{href:"https:\u002F\u002Farticulo19.org\u002F",rel:[g,h,i],target:j},children:[{type:a,value:"Artículo 19"}]},{type:a,value:" pusieron el ojo para tratar de echar abajo “el dedazo” en la asignación de puestos."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Desde 2012 y hasta la fecha, activistas, investigadores y periodistas trabajan en el proyecto "},{type:b,tag:f,props:{href:"https:\u002F\u002Fdesignaciones.org\u002Ffederales\u002F#!\u002Fprincipal",rel:[g,h,i],target:j},children:[{type:a,value:C}]},{type:a,value:" para "},{type:b,tag:l,props:{},children:[{type:a,value:"analizar los procesos de selección de los titulares de las instituciones"}]},{type:a,value:". Los objetivos están claros: primero, contar con mayor transparencia y participación ciudadana en los nombramientos; y, segundo, que las personas que ocupan los cargos públicos tengan experiencia y cuenten con capacidad probada en el tema."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:u},{type:b,tag:f,props:{href:"https:\u002F\u002Fwww.arenapublica.com\u002Fblog-ethos-laboratorio\u002Fcuatro-formas-creativas-en-las-que-colaboran-los-think-tanks-con-periodistas",rel:[g,h,i],target:j},children:[{type:a,value:x}]}]}]},dir:p,path:"\u002Fcolumnas\u002Fcuatro_formas_creativas_en_las_que_colaboran_los_think_tanks_con_periodistas",extension:q,createdAt:"2023-06-19T05:11:57.687Z",updatedAt:D},{slug:"el_contrapeso_gubernamental_a_la_baja",description:"\nEn términos muy generales, los think tanks son centros de investigación que buscan mejoras en las políticas públicas de los distintos países en los que operan. Las diferencias entre éstos son marcadas, pues mientras unos se enfocan en analizar múltiples temas, otros tienen únicamente una línea de investigación. Algunas organizaciones cuentan con cientos de empleados, sin embargo, el equipo de otros apenas se cuenta con los dedos de una mano.",title:"¿EL CONTRAPESO GUBERNAMENTAL A LA BAJA?",date:"2022-02-22T23:44:29.610Z",img:"https:\u002F\u002Fucarecdn.com\u002F1fd5c811-6354-462c-b33a-04b627a7742d\u002F",autor:"Liliana Alvarado",medio:"El Economista",link:"https:\u002F\u002Fwww.eleconomista.com.mx\u002Fopinion\u002FEl-contrapeso-gubernamental-a-la-baja-20220222-0057.html",category:n,extracto:"En términos muy generales, los *think tanks* son centros de investigación que buscan mejoras en las políticas públicas de los distintos países en los que operan. Las diferencias entre éstos son marcadas, pues mientras unos se enfocan en analizar múltiples temas, otros tienen únicamente una línea de investigación",toc:[],body:{type:m,children:[{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:E},{type:b,tag:e,props:{},children:[{type:a,value:k}]},{type:a,value:" son centros de investigación que buscan mejoras en las políticas públicas de los distintos países en los que operan. Las diferencias entre éstos son marcadas, pues mientras unos se enfocan en analizar múltiples temas, otros tienen únicamente una línea de investigación. Algunas organizaciones cuentan con cientos de empleados, sin embargo, el equipo de otros apenas se cuenta con los dedos de una mano. "},{type:a,value:" Otra diferencia entre ellos es el tipo de relación que tienen con su respectivo gobierno. En algunos países los "},{type:b,tag:e,props:{},children:[{type:a,value:k}]},{type:a,value:" asesoran y colaboran de forma cercana con las autoridades, pues se valora significativamente su capacidad y conocimiento técnico en las diferentes temáticas. No obstante, en otras naciones los "},{type:b,tag:e,props:{},children:[{type:a,value:k}]},{type:a,value:" adquieren un papel de "},{type:b,tag:e,props:{},children:[{type:a,value:F}]},{type:a,value:", haciendo referencia a la figura de un perro guardián que tiene como objetivo realizar tareas de vigilancia y monitoreo. Es más común que las organizaciones tomen este papel cuando el país enfrenta debilidades importantes en materia de transparencia, rendición de cuentas, anticorrupción, entre otros temas que requieren un señalamiento o voz de denuncia."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"En este sentido, los "},{type:b,tag:e,props:{},children:[{type:a,value:F}]},{type:a,value:" forman parte del conjunto de contrapesos al gobierno. A la lista se suman algunos medios de comunicación, periodistas, el empresariado, los organismos autónomos y electorales, entre otros. No obstante, de esta lista, tal vez uno de los contrapesos menos analizados y conocidos son los "},{type:b,tag:e,props:{},children:[{type:a,value:k}]},{type:a,value:". Ello se relaciona con el hecho de que su trabajo en ocasiones se confunde con el de la academia o incluso con organizaciones activistas."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Recientemente la plataforma global On Think Tanks presentó el Open Think Tanks Directory, que incluye un documento de análisis sobre los "},{type:b,tag:e,props:{},children:[{type:a,value:k}]},{type:a,value:" en el continente americano. De acuerdo con el reporte, los temas más comunes que abordan las organizaciones en Latinoamérica y el Caribe (LAC) en orden de importancia son: medio ambiente, política social, gobernanza\u002Ftransparencia y justicia\u002Fderechos humanos."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"No sorprende que en nuestra región algunas de las prioridades de las organizaciones sean los temas de gobernanza\u002Ftransparencia así como justicia\u002Fderechos humanos. Los problemas en dichos temas son profundos y se requiere mostrar con datos y evidencia cuáles son las áreas de mejora. Otro dato interesante del reporte se refiere al número de "},{type:b,tag:e,props:{},children:[{type:a,value:k}]},{type:a,value:" en cada país: Brasil (65), Argentina (54), Chile (52) y México (43). En el otro extremo tenemos a países con un número muy reducido: Honduras (4), Nicaragua (3) y Belice (1). Un análisis más profundo nos permitiría conocer su antigüedad, presupuesto, fuentes de financiamiento, así como valorar el impacto e incidencia que tienen las organizaciones en las políticas públicas del país."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Cuando analizamos la tendencia de "},{type:b,tag:e,props:{},children:[{type:a,value:k}]},{type:a,value:" creados por década y por región, se aprecia que, tanto en el mundo como en América del Norte y Latinoamérica, la creación de este tipo de instituciones va a la baja. Particularmente, en América Latina y el Caribe, la mayoría de este tipo de organizaciones se crearon entre 1990 y el 2009."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Dado este escenario, la pregunta adecuada sería ¿los think tanks como contrapeso, van a la baja? La respuesta es no. Hoy en día los "},{type:b,tag:e,props:{},children:[{type:a,value:k}]},{type:a,value:" son más necesarios que nunca. En América Latina, por ejemplo, la corrupción no ha ido mejorando y tampoco lo han hecho temas como la seguridad, justicia, defensa de los derechos humanos, entre otros."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Lo que sí ha pasado es que las condiciones en las que trabajan los "},{type:b,tag:e,props:{},children:[{type:a,value:k}]},{type:a,value:" y otros actores que son contrapeso del gobierno en la región, se han vuelto más difíciles. Actualmente en algunos países se condena a quienes los financian, se persigue a quienes los dirigen y se intimida a sus miembros. En un contexto como este, es fácil entender que Nicaragua, donde el presidente Daniel Ortega ha perseguido a opositores, disidentes y periodistas para mantenerse en el poder, solo tenga tres."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Hoy más que nunca hay que generar conciencia sobre la importancia de estas organizaciones. De manera particular, preocupa que con el paso del tiempo se están creando menos "},{type:b,tag:e,props:{},children:[{type:a,value:k}]},{type:a,value:". Las razones pueden ser diversas, sin embargo, el resultado es el mismo. Existen menos organizaciones en la región que están vigilando el actuar de los gobiernos y que están presionando para contar con mejores democracias, gobernanza y condiciones de vida para la población."}]},{type:a,value:d}]},excerpt:{type:m,children:[{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:E},{type:b,tag:e,props:{},children:[{type:a,value:k}]},{type:a,value:" son centros de investigación que buscan mejoras en las políticas públicas de los distintos países en los que operan. Las diferencias entre éstos son marcadas, pues mientras unos se enfocan en analizar múltiples temas, otros tienen únicamente una línea de investigación. Algunas organizaciones cuentan con cientos de empleados, sin embargo, el equipo de otros apenas se cuenta con los dedos de una mano."}]}]},dir:p,path:"\u002Fcolumnas\u002Fel_contrapeso_gubernamental_a_la_baja",extension:q,createdAt:"2023-06-19T05:11:57.867Z",updatedAt:D}]}],fetch:{},mutations:[]}}("text","element","p","\n","em","a","nofollow","noopener","noreferrer","_blank","think tanks","strong","root","think-tanks","think tank","\u002Fcolumnas",".md","Este País","Mejorar la transparencia y eficiencia del Estado mexicano es algo que sí se puede lograr. Hay muchos problemas que enfrenta México que dependen de factores externos. Hacer más dinámica la economía estadounidense, reducir la demanda mundial de cocaína y heroína o evitar que Donald Trump salga electo son cosas que los mexicanos no pueden realizar.","think","Publicado en: ","The radicalisation and polarisation of perspectives hinder dialogue and consensus-building. This growing divide among actors is not only present in populist governments but also in other regimes undergoing processes of democratic backsliding, where core values such as freedom of expression, civic participation, the rule of law, and tolerance are increasingly undermined.","2025-11-25T01:24:03.234Z","Arena Pública","5013 homicidios en la Ciudad de México"," y ","https:\u002F\u002Fcontralacorrupcion.mx\u002F","Mexicanos contra la Corrupción y la Impunidad ","Designaciones públicas","2022-09-15T15:48:00.227Z","En términos muy generales, los ","watch dogs")));